import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"32、【恒】 巽下震上","description":"周易口诀义 - 32、【恒】 巽下震上","frontmatter":{"title":"32、【恒】 巽下震上","description":"周易口诀义 - 32、【恒】 巽下震上"},"headers":[],"relativePath":"zh/classics/koujueyi/034.md","filePath":"zh/classics/koujueyi/034.md"}'),r={name:"zh/classics/koujueyi/034.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_32、【恒】-巽下震上" tabindex="-1">32、【恒】 巽下震上 <a class="header-anchor" href="#_32、【恒】-巽下震上" aria-label="Permalink to “32、【恒】 巽下震上”">​</a></h1><p>彖曰：「恒」，久也。刚上而柔下，雷风相与，巽而动，刚柔皆应，恒。「恒亨无咎利贞」，久于其道也。天地之道，恒久而不已也。「利有攸往」，终则有始也。日月得天而能久照，四时变化而能久成，圣人久于其道而天下化成。观其所恒，而天地万物之情可见矣！象曰：雷风，恒。君子以立不易方。</p><p>初六：浚恒，贞凶，无攸利。</p><p>象曰：「浚恒」之「凶」，始求深也。</p><p>九二：悔亡。</p><p>象曰：九二「悔亡」，能久中也。</p><p>九三：不恒其德，或承之羞，贞吝。</p><p>象曰：「不恒其德」，无所容也。</p><p>九四：田无禽。象曰：久非其位，安得禽也！</p><p>六五：恒其德，贞。妇人吉，夫子凶。</p><p>象曰：「妇人贞吉」，从一而终也；夫子制义，从妇凶也。</p><p>上六，振恒，凶。</p><p>象曰：「振恒」在上，大无功也。</p><p>解读</p><p>恒亨者，恒，久也；恒久之道，所贵变通，不能变通，无由长久，故系辞云「易穷则变，变则通，通则久」是也。「无咎，利贞，利有攸往」者，恒而亨，以济三事也。谓既变通，即无咎过，故利以修正，正道既行，即何往不利也。象曰：「雷风，恒」，先儒皆云：雷资风而益远，风假雷以增威，故「君子以立不易方」者，方，道也；言君子立身修行，举事合宜，不移其道，宜于世俗也。</p><p>「初六，浚恒，贞凶，无攸利」者，浚，深也；初六处恒之始，即合渐渐以求于恒，而乃浚然使深深为恒，是凶正害德，无施而利，故「贞凶，无攸利」也。</p><p>九二，悔亡。以阳居阴，位既不正，所以有悔，守其谦道，所以「悔亡」也。</p><p>九三「不恒其德，或承之羞，贞吝」者，居下卦之上，即是进慕高位；处上卦之下，又欲静退自守，故不恒守其一德，是执心不定，德行无恒，即有耻辱至焉。以此为正，亦可贱矣，故「贞吝」也。</p><p>九四：田无禽者，畋猎也，禽，喻有功也。处恒之时，位既不正，即是田猎无所获，喻有事而无功也。</p><p>六五：恒其德，贞。妇人吉，夫子凶。处恒之时而得尊位，当须普亲天下，而乃专志在二，即是执守一德，故曰「恒其德，贞」也。既不能广亲贤德，守一而已，斯乃妇人之道。若譬之丈夫，即致凶灾，故「夫子凶」也。</p><p>上六：振恒。凶者，振躁动也。处夫动极，即合安静，无为无事而已。反以躁动求为，即有凶危及也。</p>',21)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
